func (s *Store) buildShips() {
	primary := map[string]v.M{}
	for _, row := range objectRows("encyclopedia-reference-ships.json") {
		primary[v.Str(row["key"])] = row
	}
	for _, raw := range objectRows("encyclopedia-ships.json") {
		key := v.Str(raw["key"])
		facts := primary[key]
		manufacturer := v.Text(raw["manufacturer"], facts["manufacturer"], "Не указано")
		pad := v.Str(raw["pad"])
		if pad == "" {
			pad = map[int]string{1: "S", 2: "M", 3: "L"}[v.Int(facts["pad"])]
		}
		padTitle := map[string]string{"S": "Малая", "M": "Средняя", "L": "Большая"}[pad]
		role := shipRoles[key]
		e := Entry{ID: "ship/" + key, Category: "ships", Group: "ship-" + slug(manufacturer), Title: v.Str(raw["name"]), Subtitle: role[0], Description: role[1], Properties: []Property{{Label: "Производитель", Value: manufacturer}, {Label: "Площадка", Value: padTitle}}, Badges: []Badge{{Label: "Площадка " + pad}, {Label: role[0]}}}
		s.groupNames[e.Group] = manufacturer
		stats := [][]string{}
		if mass := v.Num(raw["hullMass"]); mass > 0 {
			stats = append(stats, []string{"Масса корпуса", fmt.Sprintf("%g т", mass)})
		} else if mass := v.Num(facts["hullMass"]); mass > 0 {
			stats = append(stats, []string{"Масса корпуса", fmt.Sprintf("%g т", mass)})
		}
		crew := max(v.Int(raw["crew"]), v.Int(facts["crew"])+1)
		crew = max(crew, v.Int(facts["seats"]))
		if crew > 0 {
			stats = append(stats, []string{"Мест экипажа", fmt.Sprint(crew)})
		}
		if raw["utilitySlots"] != nil {
			stats = append(stats, []string{"Служебные крепления", v.Str(raw["utilitySlots"])})
		} else if facts["utilitySlots"] != nil {
			stats = append(stats, []string{"Служебные крепления", v.Str(facts["utilitySlots"])})
		}
		for _, pair := range []struct{ key, title, unit string }{{"speed", "Скорость", " м/с"}, {"boost", "Форсаж", " м/с"}, {"shields", "Щит в базовой комплектации", " МДж"}, {"armour", "Прочность корпуса", ""}} {
			if value := v.Str(facts[pair.key]); value != "" && value != "0" {
				stats = append(stats, []string{pair.title, value + pair.unit})
			}
		}
		e.Sections = append(e.Sections, Section{ID: "specifications", Title: "Характеристики корпуса", Type: "table", Columns: []string{"Параметр", "Значение"}, Rows: stats})
		mounts := [][]string{}
		hardpoints := v.Rows(raw["hardpoints"])
		if len(hardpoints) == 0 {
			hardpoints = v.Rows(facts["hardpoints"])
		}
		for _, mount := range hardpoints {
			mounts = append(mounts, []string{fmt.Sprintf("Оружие: класс %s", v.Str(mount["grade"])), v.Str(mount["count"])})
		}
		optional := []string{}
		optionalSlots := v.Arr(raw["optionalSlots"])
		if len(optionalSlots) == 0 {
			optionalSlots = v.Arr(facts["optionalSlots"])
		}
		for _, size := range optionalSlots {
			optional = append(optional, v.Str(size))
		}
		if len(optional) > 0 {
			mounts = append(mounts, []string{"Классы дополнительных отсеков", strings.Join(optional, ", ")})
		}
		for _, restricted := range v.Rows(facts["restrictedSlots"]) {
			mounts = append(mounts, []string{v.Str(restricted["kind"]) + " отсек", "Класс " + v.Str(restricted["size"])})
		}
		coreNames := []string{"Силовая установка", "Двигатели", "FSD", "Жизнеобеспечение", "Распределитель питания", "Сенсоры", "Топливный бак"}
		for i, size := range v.Arr(facts["coreSlots"]) {
			if i < len(coreNames) {
				mounts = append(mounts, []string{coreNames[i], "Класс " + v.Str(size)})
			}
		}
		if len(mounts) > 0 {
			e.Sections = append(e.Sections, Section{ID: "mounts", Title: "Подвески и отсеки", Type: "table", Columns: []string{"Оснащение", "Количество / классы"}, Rows: mounts})
		}
		e.Sections = append(e.Sections, Section{ID: "outfitting", Title: "Подготовка рабочей сборки", Type: "requirements", Items: []Item{{Title: "Базовая комплектация", Text: "Справочные скорость, форсаж и щит относятся к базовому оснащению. Модули, масса, распределение энергии и модификации меняют фактические показатели."}, {Title: "Дальность после загрузки", Text: "Масса топлива, груза и установленного оборудования меняет дальность. Базовые характеристики корпуса не заменяют расчёт выбранной сборки.", EntryID: "module/fsd"}, {Title: "Энергия и охлаждение", Text: "Проверьте работу модулей при выпущенном оружии, приоритеты питания и запас температуры.", EntryID: "module/pp"}, {Title: "Резерв восстановления", Text: "После покупки корпуса оставьте деньги на модули, груз и восстановление корабля.", EntryID: "article/ship-budget"}}})
		r := s.add(e, v.Str(raw["symbol"]), manufacturer)
		r.imageKey = "ship-" + key
		r.relatedIDs = []string{"module/fsd", "module/pp", "module/pd", "module/sg", "article/optional-modules", "article/ship-budget"}
	}
}
